const ehSabado = diaSemanaNum === 6;

const total = eventosManha.length + eventosTarde.length;

const nomeAtendente = $('Carregar Neg?cio p/ Relat?rio').first().json.nome_atendente_ia || 'Assistente';
const nomeEmpresa = $('Carregar Neg?cio p/ Relat?rio').first().json.nome_empresa || 'Empresa';

let relatorio = `?? *RELAT?RIO DA AGENDA*\n`;
relatorio += `?? *${diaNome}, ${dataFormatada}*\n`;
relatorio += `????????????????????\n\n`;

relatorio += `?? *MANH? (8h ?s 12h)*\n`;
if (eventosManha.length > 0) {
  relatorio += eventosManha.join('\n') + '\n';
} else {
  relatorio += `   ? Nenhum agendamento\n`;
}

if (ehSabado) {
