return [{ json: { relatorio, total, data: dataFormatada } }];

const raw = $input.first().json;
const body = raw.body || raw;

const evento = (body?.event || '').toLowerCase();

// ACEITA APENAS messages.upsert
if (evento !== 'messages.upsert') {
  return [];
}

const fromMe = body?.data?.key?.fromMe ?? false;
const remoteJid = body?.data?.key?.remoteJid || '';
const messageId = body?.data?.key?.id || '';
const instance = body?.instance || body?.instanceName || '';

const msg = body?.data?.message || {};
const text = msg.conversation || msg.extendedTextMessage?.text || '';
const hasContent = !!(text || msg.audioMessage || msg.imageMessage || msg.documentMessage);
const pushName = body?.data?.pushName || '';

const isGroup = remoteJid.endsWith('@g.us');
const isComando = text.trim().startsWith('#');

if (isGroup) return [];

// fromMe com comando SEMPRE passa
if (fromMe && isComando) {
  return [{ json: {
    instance: String(instance),
    remoteJid,
    telefone: remoteJid.replace(/@s\.whatsapp\.net$/, ''),
    text,
    pushName,
    fromMe,
    evento,
    messageId,
    body
  }}];
}

if (!hasContent && !fromMe) return [];

return [{ json: {
  instance: String(instance),
  remoteJid,
  telefone: remoteJid.replace(/@s\.whatsapp\.net$/, ''),
  text,
  pushName,
  fromMe,
  evento,
  messageId,
  body
}}];

const items = $input.all();
const results = [];

for (const item of items) {
  const data = item.json;
  const text = (data.text || '').trim();
  const fromMe = data.fromMe === true;

  let acao = 'cliente_falou';

  if (fromMe) {
    acao = text.startsWith('#') ? 'comando_proprietario' : 'humano_falou';
  }

  results.push({ json: { ...data, _acao: acao } });
}

return results;
